import events from './events.json' with {type:'json'};

const DEFAULT_PAGE_SIZE = 2;
const MAX_PAGE_SIZE = 3;
const MIN_PAGE_SIZE = 1;

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({ i: index }), 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    const json = Buffer.from(cursor, 'base64').toString('utf8');
    parsed = JSON.parse(json);
  } catch (e) {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Unknown cursor');
  }
  if (!Number.isInteger(parsed.i) || parsed.i < 0) {
    throw new Error('Unknown cursor');
  }
  return parsed.i;
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events with optional cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string' },
          page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE }
        },
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'events_list') {
    throw new Error(`Unknown tool: ${name}`);
  }
  // Validate extra fields
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  // Validate cursor
  let cursor = undefined;
  if ('cursor' in args) {
    cursor = args.cursor;
    if (typeof cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
  }
  // Validate page_size
  let pageSize = DEFAULT_PAGE_SIZE;
  if ('page_size' in args) {
    pageSize = args.page_size;
    if (!Number.isInteger(pageSize) || pageSize < MIN_PAGE_SIZE || pageSize > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
  }
  // Determine start index
  let start = 0;
  if (cursor !== undefined) {
    start = decodeCursor(cursor);
    if (start >= events.length) {
      throw new Error('Unknown cursor');
    }
  }
  const page = events.slice(start, start + pageSize);
  const end = start + pageSize;
  const result = { events: page };
  if (end < events.length) {
    result.next_cursor = encodeCursor(end);
  } else {
    result.next_cursor = null;
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
```

