+const TOOL_NAME = 'events_list';
+const ALLOWED_ARGS = ['cursor', 'page_size'];
+const DEFAULT_PAGE_SIZE = 2;
+const MAX_PAGE_SIZE = 3;
+
+function encodeCursor(index) {
+  return Buffer.from(JSON.stringify({ i: index }), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  let decoded;
+  try {
+    decoded = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (
+    !decoded || typeof decoded !== 'object' || Array.isArray(decoded) ||
+    typeof decoded.i !== 'number' || !Number.isInteger(decoded.i) ||
+    decoded.i < 0 || decoded.i > events.length
+  ) {
+    throw new Error('Unknown cursor');
+  }
+  return decoded.i;
+}
+
+export async function listTools() {
+  return [{
+    name: TOOL_NAME,
+    description: 'List events in source order with optional cursor pagination.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        cursor: { type: 'string', description: 'Opaque pagination cursor returned by a previous call.' },
+        page_size: { type: 'integer', minimum: 1, maximum: 3, description: 'Number of events per page (1-3, default 2).' }
+      },
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== TOOL_NAME) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
+    throw new Error('Invalid arguments');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.includes(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+
+  let cursor;
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('cursor must be a string');
+    }
+    cursor = args.cursor;
+  }
+
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if (args.page_size !== undefined) {
+    if (
+      typeof args.page_size !== 'number' || !Number.isInteger(args.page_size) ||
+      args.page_size < 1 || args.page_size > MAX_PAGE_SIZE
+    ) {
+      throw new Error('page_size must be an integer from 1 to 3');
+    }
+    pageSize = args.page_size;
+  }
+
+  let start = 0;
+  if (cursor !== undefined) {
+    start = decodeCursor(cursor);
+  }
+
+  const slice = events.slice(start, start + pageSize);
+  const nextStart = start + pageSize;
+  const result = { events: slice };
+  if (nextStart < events.length) {
+    result.next_cursor = encodeCursor(nextStart);
+  }
+
+  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
